from lease_vs_buy import annuity_payment, npv_buy, npv_lease, recommend

# Hard-coded from the annuity formula: 60000 * 0.07 / (1 - 1.07**-5) = 14633.44
EXPECTED_LOAN_PAYMENT = 14_633.44


def test_loan_payment_matches_annuity_formula():
    assert round(annuity_payment(60_000, 0.07, 5), 2) == EXPECTED_LOAN_PAYMENT


def test_both_npv_negative():
    assert npv_buy() < 0
    assert npv_lease() < 0


def test_decision_flips_at_lower_lease_rate():
    assert recommend(lease_payment=13_500) != recommend(lease_payment=10_000)


def test_zero_tax_changes_buy_npv():
    assert npv_buy(tax_rate=0.25) != npv_buy(tax_rate=0.0)


def test_baseline_recommendation_is_consistent_with_npvs():
    buy, lease = npv_buy(), npv_lease()
    expected = "lease" if lease > buy else "buy"
    assert recommend() == expected
